(function () {
  'use strict';
  // Social Security claiming breakeven. Month t counts from age 62 (t = 0). A claim at age c pays
  //   PIA x factor(c) x (1 + COLA)^floor(t / 12) in every month t >= (c - 62) x 12,
  // and each payment is discounted to age 62 at (1 + discount)^(-t / 12). The breakeven age between
  // an earlier and a later claim is the first month the later claim's running total catches up,
  // counted to the end of the month whose payment closes the gap.
  // Checked in Node (scratch tests): PIA $1,000, FRA 67, no COLA or discount -> 62 pays $700,
  //   70 pays $1,240; breakeven 62 vs 67 = 700t = 1000(t - 60) -> t = 200 months = age 78 and 8
  //   months; 67 vs 70 = 1,240(t - 96) = 1,000(t - 60) -> t = 246 = age 82 and 6 months;
  //   62 vs 70: 700t = 1,240(t - 96) -> t = 220.4, so the 221st month -> age 80 and 5 months. FRA 66 and 10 months
  //   (born 1959) claiming at 62 -> 70.833%, at 67 -> 101.33%. A COLA moves the breakevens
  //   earlier (2.5%: 62 vs 67 -> age 76 and 9 months); a discount rate moves them later (3%: 62 vs 70 -> age 84 and
  //   5 months). Both match an independent Python loop.
  // ---- SOCIAL SECURITY RULES (benefit year 2026) -----------------------------------------
  // FRA schedule: 42 U.S.C. 416(l) (66 for 1943-54, +2 months a year for 1955-59, 67 from 1960).
  // Early claiming: -5/9 of 1% a month for the first 36 months, -5/12 of 1% beyond: 20 CFR 404.410.
  // Delayed retirement credits: +2/3 of 1% a month (8% a year) up to age 70: 20 CFR 404.313.
  var BENEFIT_YEAR = 2026;
  var FIRST_AGE = 62, LAST_AGE = 70;
  // ---------------------------------------------------------------------------------------

  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function fraMonths(birthYear) {
    if (birthYear <= 1954) return 66 * 12;
    if (birthYear >= 1960) return 67 * 12;
    return 66 * 12 + (birthYear - 1954) * 2;
  }
  function factor(claimMonths, fra) {
    var diff = claimMonths - fra;
    if (diff < 0) {
      var early = -diff;
      return 1 - (Math.min(early, 36) * 5 / 900) - (Math.max(0, early - 36) * 5 / 1200);
    }
    return 1 + Math.min(diff, LAST_AGE * 12 - fra) * 2 / 300;
  }
  function ageLabel(months) {
    var y = Math.floor(months / 12), m = months % 12;
    return y + (m ? ' and ' + m + (m === 1 ? ' month' : ' months') : '');
  }

  // Monthly running totals from age 62 to `endAge` (exclusive) for one claiming age.
  function stream(pia, fra, claimAge, cola, disc, endAge) {
    var start = (claimAge - FIRST_AGE) * 12, first = pia * factor(claimAge * 12, fra);
    var total = 0, cum = [], n = (endAge - FIRST_AGE) * 12;
    var monthlyDisc = Math.pow(1 + disc, 1 / 12);
    for (var t = 0; t < n; t++) {
      if (t >= start) total += first * Math.pow(1 + cola, Math.floor(t / 12)) / Math.pow(monthlyDisc, t);
      cum.push(total);
    }
    return { claimAge: claimAge, first: first * Math.pow(1 + cola, claimAge - FIRST_AGE), cum: cum };
  }

  // Age in months when the later claim's running total first reaches the earlier one's: the end of
  // the month whose payment closes the gap (payments arrive monthly, so this is exact to the month).
  function breakeven(early, late) {
    for (var t = 0; t < late.cum.length; t++) {
      if (late.cum[t] > 0 && late.cum[t] >= early.cum[t] - 1e-6) return FIRST_AGE * 12 + t + 1;
    }
    return null;
  }

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function update() {
    var pia = num('sdPia'), birth = Math.round(num('sdBirth')), life = Math.round(num('sdLife')),
        cola = num('sdCola'), disc = num('sdDiscount');
    if (isNaN(cola)) cola = 0;
    if (isNaN(disc)) disc = 0;
    var ages = ['sdAgeA', 'sdAgeB', 'sdAgeC'].map(function (id) { return parseInt(document.getElementById(id).value, 10); });
    var error = document.getElementById('sdError');
    var bad = [pia, birth, life].some(isNaN) || pia < 0 || birth < 1943 || birth > 2010 || life < 63 || life > 110 ||
              cola < 0 || cola > 10 || disc < 0 || disc > 15;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a benefit of 0 or more, a birth year from 1943 to 2010, a life expectancy from 63 to 110, ' +
                          'a COLA from 0 to 10% and a discount rate from 0 to 15%.';
      return;
    }
    var fra = fraMonths(birth);
    set('sdFra', 'Full retirement age: ' + ageLabel(fra) + '.');
    var horizon = 105, endLife = life; // breakevens are searched up to age 105
    var streams = ages.map(function (a) { return stream(pia, fra, a, cola / 100, disc / 100, Math.max(horizon, life)); });
    var discounted = disc > 0;
    set('sdTotalHead', discounted ? 'Value at 62 to life expectancy' : 'Total to life expectancy');
    set('sdScheduleNote', discounted
      ? 'Running totals by the end of each year of age, each payment discounted to its value at age 62.'
      : 'Total received by the end of each year of age under each claiming option.');

    var idx = (endLife - FIRST_AGE) * 12 - 1;
    var bestI = 0, totals = streams.map(function (s) { return idx >= 0 ? s.cum[idx] : 0; });
    totals.forEach(function (v, i) { if (v > totals[bestI] + 0.005) bestI = i; });
    var letters = ['A', 'B', 'C'];
    document.getElementById('sdOptions').innerHTML = streams.map(function (s, i) {
      return '<tr><td>' + letters[i] + ': ' + s.claimAge + ' (' + (factor(s.claimAge * 12, fra) * 100).toFixed(1) + '%)</td><td>' +
             whole.format(s.first) + '/mo</td><td>' + whole.format(totals[i]) + '</td></tr>';
    }).join('');

    var pairs = [[0, 1, 'sdBe1'], [1, 2, 'sdBe2'], [0, 2, 'sdBe3']];
    pairs.forEach(function (p) {
      var a = streams[p[0]], b = streams[p[1]];
      set(p[2] + 'Term', letters[p[0]] + ' (' + a.claimAge + ') vs ' + letters[p[1]] + ' (' + b.claimAge + ')');
      if (a.claimAge === b.claimAge) { set(p[2], 'Same age'); return; }
      var early = a.claimAge < b.claimAge ? a : b, late = a.claimAge < b.claimAge ? b : a;
      var be = pia > 0 ? breakeven(early, late) : null;
      set(p[2], be === null ? 'Not before ' + horizon : 'Age ' + ageLabel(be));
    });

    var ranked = totals.slice().sort(function (x, y) { return y - x; });
    set('sdBest', pia > 0
      ? 'If you live to ' + life + ', claiming at ' + streams[bestI].claimAge + ' gives the most' +
        (discounted ? ' in value at age 62' : '') + ': ' + whole.format(totals[bestI]) +
        (ranked[1] < ranked[0] ? ', ' + whole.format(ranked[0] - ranked[1]) + ' more than the next option.' : '.')
      : 'Enter your monthly benefit to compare claiming ages.');

    set('sdColA', 'Claim at ' + ages[0]); set('sdColB', 'Claim at ' + ages[1]); set('sdColC', 'Claim at ' + ages[2]);
    var rows = [];
    for (var age = FIRST_AGE; age < Math.max(life, LAST_AGE + 1); age++) {
      var k = (age - FIRST_AGE + 1) * 12 - 1;
      rows.push('<tr><td>' + age + '</td><td>' + whole.format(streams[0].cum[k]) + '</td><td>' +
                whole.format(streams[1].cum[k]) + '</td><td>' + whole.format(streams[2].cum[k]) + '</td></tr>');
    }
    document.getElementById('sdSchedule').innerHTML = rows.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('sdForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
